"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowUpRight } from "lucide-react";

const experiences = [
  {
    period: "2023 - Present",
    title: "Python Django Full-Stack Developer",
    company: "Mystro Training",
    description:
      "Build and maintain full-stack applications using Django framework. Work closely with modern technologies including Docker, Celery, Redis, and Vue.js to implement and advocate for best practices in web development.",
    highlights: [
      "Created responsive websites with HTML, CSS, Bootstrap and JavaScript",
      "Built automation scripts with Python for workflow optimization",
      "Developed RESTful APIs with Django REST Framework",
      "Integrated payment systems including Stripe",
      "Deployed applications to cloud using Render",
    ],
    tech: ["Python", "Django", "DRF", "Docker", "Vue.js", "Redis", "Celery"],
  },
];

const education = {
  period: "2023 - 2024",
  degree: "Full-Stack Python & Web Development",
  school: "Mystro E-Learning School",
  type: "Bootcamp",
};

export function ExperienceSection() {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section
      ref={sectionRef}
      id="experience"
      className="relative py-32 px-6 lg:px-12"
    >
      {/* Refined cinematic background matching project colors */}
      <div className="absolute inset-0 overflow-hidden">
        {/* Dynamic primary-color gradient base */}
        <div className="absolute inset-0">
          <div 
            className="absolute inset-0 opacity-25"
            style={{
              background: `linear-gradient(135deg, 
                rgba(94, 234, 212, 0.12) 0%, 
                rgba(94, 234, 212, 0.08) 25%, 
                rgba(94, 234, 212, 0.06) 50%, 
                rgba(94, 234, 212, 0.08) 75%, 
                rgba(94, 234, 212, 0.12) 100%)`,
              animation: 'gradient-shift 20s ease-in-out infinite',
            }}
          />
        </div>
        
        {/* 3D morphing geometric shapes with project colors */}
        <div className="absolute inset-0 perspective-1000">
          {[...Array(6)].map((_, i) => (
            <div
              key={i}
              className="absolute preserve-3d"
              style={{
                width: `${60 + i * 25}px`,
                height: `${60 + i * 25}px`,
                top: `${15 + i * 10}%`,
                left: `${8 + i * 14}%`,
                animation: `morph-3d ${15 + i * 2}s ease-in-out infinite`,
                animationDelay: `${i * 0.8}s`,
                transformStyle: 'preserve-3d',
              }}
            >
              <div 
                className="absolute inset-0 rounded-lg border border-primary/20"
                style={{
                  background: `linear-gradient(45deg, 
                    rgba(94, 234, 212, 0.15), 
                    rgba(94, 234, 212, 0.08), 
                    rgba(94, 234, 212, 0.12))`,
                  backdropFilter: 'blur(6px)',
                  boxShadow: '0 4px 20px rgba(94, 234, 212, 0.15)',
                }}
              />
              <div 
                className="absolute inset-0 rounded-lg"
                style={{
                  background: 'linear-gradient(135deg, transparent, rgba(94, 234, 212, 0.08))',
                  transform: 'rotateY(180deg) translateZ(15px)',
                }}
              />
            </div>
          ))}
        </div>
        
        {/* Refined particle system with primary color */}
        <div className="absolute inset-0">
          {[...Array(25)].map((_, i) => (
            <div
              key={i}
              className="absolute w-1.5 h-1.5 rounded-full"
              style={{
                background: `radial-gradient(circle, 
                  rgba(94, 234, 212, ${0.7 + Math.random() * 0.3}) 0%, 
                  rgba(94, 234, 212, ${0.4 + Math.random() * 0.3}) 50%, 
                  transparent 100%)`,
                top: `${Math.random() * 100}%`,
                left: `${Math.random() * 100}%`,
                animation: `particle-trail ${5 + Math.random() * 4}s ease-in-out infinite`,
                animationDelay: `${Math.random() * 3}s`,
                boxShadow: `0 0 ${8 + Math.random() * 15}px rgba(94, 234, 212, 0.4)`,
              }}
            />
          ))}
        </div>
        
        {/* Subtle mesh gradient with project colors */}
        <div className="absolute inset-0 opacity-15">
          <div 
            className="absolute inset-0"
            style={{
              background: `
                radial-gradient(circle at 25% 25%, rgba(94, 234, 212, 0.12) 0%, transparent 50%),
                radial-gradient(circle at 75% 75%, rgba(94, 234, 212, 0.08) 0%, transparent 50%),
                radial-gradient(circle at 50% 50%, rgba(94, 234, 212, 0.06) 0%, transparent 50%)
              `,
              animation: 'mesh-pulse 10s ease-in-out infinite',
            }}
          />
        </div>
        
        {/* Floating glassmorphism elements with primary accent */}
        <div className="absolute inset-0">
          {[...Array(4)].map((_, i) => (
            <div
              key={i}
              className="absolute rounded-xl backdrop-blur-sm border border-primary/10"
              style={{
                width: `${40 + i * 15}px`,
                height: `${15 + i * 8}px`,
                top: `${25 + i * 18}%`,
                right: `${15 + i * 10}%`,
                background: `linear-gradient(135deg, 
                  rgba(94, 234, 212, 0.08), 
                  rgba(94, 234, 212, 0.03))`,
                animation: `glass-float ${12 + i * 3}s ease-in-out infinite`,
                animationDelay: `${i * 1.5}s`,
                boxShadow: '0 2px 15px rgba(94, 234, 212, 0.1)',
              }}
            />
          ))}
        </div>
        
        {/* Subtle animated grid with primary color */}
        <div 
          className="absolute inset-0 opacity-10"
          style={{
            backgroundImage: `
              linear-gradient(rgba(94, 234, 212, 0.15) 1px, transparent 1px),
              linear-gradient(90deg, rgba(94, 234, 212, 0.15) 1px, transparent 1px)
            `,
            backgroundSize: '60px 60px',
            transform: 'perspective(400px) rotateX(45deg)',
            transformOrigin: 'center',
            animation: 'grid-scroll 25s linear infinite',
          }}
        />
      </div>
      
      <div className="relative max-w-6xl mx-auto z-10">
        {/* Section header */}
        <div
          className={`flex items-center gap-4 mb-16 transition-all duration-700 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <span className="font-mono text-primary text-sm">02.</span>
          <h2 className="text-2xl sm:text-3xl font-bold text-foreground">Experience</h2>
          <div className="flex-1 h-px bg-border max-w-[300px]" />
        </div>

        {/* Experience Items */}
        <div className="space-y-12">
          {experiences.map((exp, index) => (
            <div
              key={exp.title}
              className={`group grid lg:grid-cols-[200px_1fr] gap-4 lg:gap-8 p-6 -mx-6 rounded-xl transition-all duration-500 hover:bg-card/50 ${
                isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
              }`}
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              {/* Period */}
              <div className="font-mono text-sm text-muted-foreground">
                {exp.period}
              </div>
              
              {/* Content */}
              <div>
                <h3 className="text-lg font-semibold text-foreground group-hover:text-primary transition-colors flex items-center gap-2">
                  {exp.title}
                  <span className="text-primary">@</span>
                  <a
                    href="#"
                    className="text-primary hover:underline underline-offset-4 inline-flex items-center gap-1"
                  >
                    {exp.company}
                    <ArrowUpRight className="w-4 h-4" />
                  </a>
                </h3>
                
                <p className="mt-3 text-muted-foreground leading-relaxed">
                  {exp.description}
                </p>
                
                <ul className="mt-4 space-y-2">
                  {exp.highlights.map((highlight, i) => (
                    <li
                      key={i}
                      className="flex items-start gap-3 text-sm text-muted-foreground"
                    >
                      <span className="text-primary mt-1">{">"}</span>
                      <span>{highlight}</span>
                    </li>
                  ))}
                </ul>
                
                <div className="flex flex-wrap gap-2 mt-6">
                  {exp.tech.map((t) => (
                    <span
                      key={t}
                      className="px-3 py-1 text-xs font-mono bg-primary/10 text-primary rounded-full"
                    >
                      {t}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Education */}
        <div
          className={`mt-20 transition-all duration-700 delay-300 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <h3 className="font-mono text-sm text-primary mb-8">{"// Education"}</h3>
          
          <div className="group grid lg:grid-cols-[200px_1fr] gap-4 lg:gap-8 p-6 -mx-6 rounded-xl hover:bg-card/50 transition-colors">
            <div className="font-mono text-sm text-muted-foreground">
              {education.period}
            </div>
            
            <div>
              <h4 className="text-lg font-semibold text-foreground group-hover:text-primary transition-colors">
                {education.degree}
              </h4>
              <p className="text-primary mt-1">{education.school}</p>
              <span className="inline-block mt-3 px-3 py-1 text-xs font-mono bg-primary/10 text-primary rounded-full">
                {education.type}
              </span>
            </div>
          </div>
        </div>

        {/* Languages */}
        <div
          className={`mt-16 transition-all duration-700 delay-400 ${
            isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          <h3 className="font-mono text-sm text-primary mb-6">{"// Languages"}</h3>
          <div className="flex flex-wrap gap-4">
            {["Arabic (Native)", "English (Fluent)", "German (Conversational)"].map((lang) => (
              <div
                key={lang}
                className="px-4 py-2 bg-card/50 rounded-lg border border-border text-sm text-foreground"
              >
                {lang}
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
